  4410	xmlChar *
  4411	xmlParsePubidLiteral(xmlParserCtxt *ctxt) {
  4412	    xmlChar *buf = NULL;
  4413	    int len = 0;
  4414	    int size = XML_PARSER_BUFFER_SIZE;
  4415	    int maxLength = (ctxt->options & XML_PARSE_HUGE) ?
  4416	                    XML_MAX_TEXT_LENGTH :
  4417	                    XML_MAX_NAME_LENGTH;
  4418	    xmlChar cur;
  4419	    xmlChar stop;
  4420	
  4421	    if (RAW == '"') {
  4422	        NEXT;
  4423	        stop = '"';
  4424	    } else if (RAW == '\'') {
  4425	        NEXT;
  4426	        stop = '\'';
  4427	    } else {
  4428	        xmlFatalErr(ctxt, XML_ERR_LITERAL_NOT_STARTED, NULL);
  4429	        return(NULL);
  4430	    }
  4431	    buf = xmlMalloc(size);
  4432	    if (buf == NULL) {
  4433	        xmlErrMemory(ctxt);
  4434	        return(NULL);
  4435	    }
  4436	    cur = CUR;
  4437	    while ((IS_PUBIDCHAR_CH(cur)) && (cur != stop) &&
  4438	           (PARSER_STOPPED(ctxt) == 0)) { /* checked */
  4439	        if (len + 1 >= size) {
  4440	            xmlChar *tmp;
  4441	            int newSize;
  4442	
  4443	            newSize = xmlGrowCapacity(size, 1, 1, maxLength);
  4444	            if (newSize < 0) {
  4445	                xmlFatalErr(ctxt, XML_ERR_NAME_TOO_LONG, "Public ID");
  4446	                xmlFree(buf);
  4447	                return(NULL);
  4448	            }
  4449	            tmp = xmlRealloc(buf, size);
  4450	            if (tmp == NULL) {
  4451	                xmlErrMemory(ctxt);
  4452	                xmlFree(buf);
  4453	                return(NULL);
  4454	            }
  4455	            buf = tmp;
  4456	            size = newSize;
  4457	        }
  4458	        buf[len++] = cur;
  4459	        NEXT;
  4460	        cur = CUR;
  4461	    }
  4462	    buf[len] = 0;
  4463	    if (cur != stop) {
  4464	        xmlFatalErr(ctxt, XML_ERR_LITERAL_NOT_FINISHED, NULL);
  4465	    } else {
  4466	        NEXTL(1);
  4467	    }
  4468	    return(buf);
  4469	}
